import { Controller, Post, Body } from '@nestjs/common';
import { OrderService } from './order.service';

// AppController depends on OrderService, which is request-scoped,
// so AppController itself loses its singleton lifetime too.
@Controller('orders')
export class AppController {
  constructor(private readonly orderService: OrderService) {}

  @Post()
  create(@Body('amount') amount: number) {
    return this.orderService.createOrder(amount);
  }
}

// app.module.ts
import { MiddlewareConsumer, Module, NestModule } from '@nestjs/common';
import { AppController } from './app.controller';
import { OrderService } from './order.service';
import { PricingService } from './pricing.service';
import { RequestContextService } from './request-context.service';
import { RequestContextMiddleware } from './request-context.middleware';

@Module({
  controllers: [AppController],
  providers: [OrderService, PricingService, RequestContextService],
})
export class AppModule implements NestModule {
  configure(consumer: MiddlewareConsumer): void {
    consumer.apply(RequestContextMiddleware).forRoutes('*');
  }
}
